const DEMO=document.documentElement.dataset.mode==='demo';
const app=document.getElementById('app');
let data=null,periodId=Number(sessionStorage.getItem('sikap_period'))||0,route='',opdFilter='all',editing=null,dirty=false,busy=false;
// Status tiap tabel (halaman aktif, kata pencarian, filter) disimpan per kunci; direset saat berpindah rute.
const tables={},tbl=k=>tables[k]??(tables[k]={page:1,q:'',f:{}}),fv=(k,n)=>tbl(k).f[n]??'all',pass=(k,n,v)=>fv(k,n)==='all'||String(fv(k,n))===String(v),matcher=k=>{const q=tbl(k).q.trim().toLowerCase();return(...f)=>!q||f.join(' ').toLowerCase().includes(q);};
function resetTables(keepFilters=false){for(const k of Object.keys(tables)){if(keepFilters){tables[k].page=1;tables[k].q='';}else delete tables[k];}}
const isAdmin=()=>['admin','admin_opd'].includes(data?.user?.role),isSuper=()=>data?.user?.role==='admin',kabupaten=()=>data?.settings?.kabupaten_name??'Hulu Sungai Selatan',roleNames={admin:'Administrator kabupaten',admin_opd:'Admin OPD',asn:'Akun ASN'},opdName=id=>data.opds.find(o=>Number(o.id)===Number(id))?.name??'',opdCode=id=>data.opds.find(o=>Number(o.id)===Number(id))?.code??'';
const inOpd=e=>!isSuper()||opdFilter==='all'||Number(e.opd_id)===Number(opdFilter);
const opdSelect=(id,label='Semua OPD')=>isSuper()&&data.opds.length>1?`<select class="select" id="${id}" style="width:auto" aria-label="Filter OPD"><option value="all">${label}</option>${data.opds.map(o=>`<option value="${o.id}" ${String(opdFilter)===String(o.id)?'selected':''}>${esc(o.name)}</option>`).join('')}</select>`:'';
const searchBox=(key,placeholder)=>`<label class="searchbox">${icon('search')}<span class="sr-only">${esc(placeholder)}</span><input class="input" id="search-${key}" data-search="${key}" value="${esc(tbl(key).q)}" placeholder="${esc(placeholder)}..."></label>`;
const filterSelect=(key,name,label,options)=>`<select class="select" style="width:auto" data-table="${key}" data-filter="${name}" aria-label="${esc(label)}"><option value="all">${esc(label)}</option>${options.map(([v,l])=>`<option value="${esc(v)}" ${String(fv(key,name))===String(v)?'selected':''}>${esc(l)}</option>`).join('')}</select>`;
const pageItems=(page,pages)=>{if(pages<=7)return Array.from({length:pages},(_,i)=>i+1);const out=[];let prev=0;for(const n of [...new Set([1,2,page-1,page,page+1,pages-1,pages])].filter(n=>n>=1&&n<=pages).sort((a,b)=>a-b)){if(n-prev>1)out.push('…');out.push(n);prev=n;}return out;};
// Potong baris sesuai halaman aktif tabel; nomor halaman dijepit agar tetap sah setelah filter berubah.
function paginate(key,rows,per=10){const t=tbl(key),pages=Math.max(1,Math.ceil(rows.length/per));t.page=Math.min(Math.max(1,t.page),pages);const start=(t.page-1)*per;return{visible:rows.slice(start,start+per),start,end:Math.min(start+per,rows.length),pages,page:t.page,total:rows.length};}
function pageNav(key,p,label,extra=''){const btn=(n,text,aria,cls='',disabled=false)=>`<button class="${cls}" data-action="page" data-table="${key}" data-value="${n}" aria-label="${aria}" ${disabled?'disabled':''} ${cls?'aria-current="page"':''}>${text}</button>`;const nav=p.pages>1?`<div class="page-buttons" role="navigation" aria-label="Navigasi halaman ${esc(label)}">${btn(p.page-1,'‹','Halaman sebelumnya','',p.page===1)}${pageItems(p.page,p.pages).map(n=>n==='…'?'<span aria-hidden="true">…</span>':btn(n,n,`Halaman ${n}`,p.page===n?'active':'')).join('')}${btn(p.page+1,'›','Halaman berikutnya','',p.page===p.pages)}</div>`:'';return`<div class="card-foot"><span>Menampilkan ${p.total?p.start+1:0}–${p.end} dari ${p.total} ${esc(label)}${extra}</span>${nav}</div>`;}
const roleLabels={atasan:'Atasan',rekan:'Rekan sejawat',bawahan:'Bawahan'},targetLabels={atasan:'Bawahan',rekan:'Rekan sejawat',bawahan:'Atasan'};
// Kondisi komposisi penilai; kuncinya peran terurut, sama dengan tabel bobot server. data.period.weights = bobot periode terpilih: dapat diubah administrator kabupaten selama draf, terkunci sejak periode dibuka.
const conditions=[['atasan,bawahan,rekan','Kondisi 1','Tiga peran'],['atasan,rekan','Kondisi 2','Tanpa bawahan'],['atasan,bawahan','Kondisi 3','Tanpa rekan sejawat']],roleColors={atasan:'#386bea',rekan:'#4bbdc1',bawahan:'#a4b7e2'};
const defaultWeights={'atasan,bawahan,rekan':{atasan:60,rekan:25,bawahan:15},'atasan,rekan':{atasan:75,rekan:25},'atasan,bawahan':{atasan:85,bawahan:15}}; // cermin Scoring::DEFAULT_WEIGHTS
const weightBar=w=>`<div class="weight-bar">${Object.entries(w).map(([r,v])=>`<span data-bar="${r}" style="width:${v}%;background:${roleColors[r]}"></span>`).join('')}</div>`;
