let assignSeq=0;
async function periods(){if(!isAdmin())return denied();const seq=++assignSeq,t=tbl('assignments');let r;try{r=await request('assignment_list',{opd_id:isSuper()&&opdFilter!=='all'?Number(opdFilter):null,role:fv('assignments','role'),status:fv('assignments','status'),q:t.q.trim(),page:t.page});}catch(err){if(seq===assignSeq)notify(err.message,true);return;}if(seq!==assignSeq||route!=='periods')return;t.page=r.page;periodsView(r);}
function periodsView(r){const p=data.period,a={length:r.stats.total},sent=r.stats.submitted,ap={visible:r.rows,start:(r.page-1)*r.per,end:(r.page-1)*r.per+r.rows.length,pages:r.pages,page:r.page,total:r.total};
 const years=[...new Set(data.periods.map(x=>String(x.start_date).slice(0,4)))].sort().reverse(),periodList=data.periods.filter(x=>pass('periods','year',String(x.start_date).slice(0,4))&&pass('periods','status',x.status)),pp=paginate('periods',periodList,8);
 const days=Math.round((new Date(p.end_date+'T12:00:00')-new Date(p.start_date+'T12:00:00'))/864e5)+1,publishedAt=p.published_at?new Date(String(p.published_at).replace(' ','T')).toLocaleString('id-ID',{day:'numeric',month:'long',year:'numeric',hour:'2-digit',minute:'2-digit'}):'—',statusHint={draft:'Penilai masih dapat ditambahkan; pegawai belum bisa mengisi.',open:'Pegawai mengisi penilaian sesuai tanggal periode.',closed:'Pengisian dikunci; hasil menunggu publikasi.',published:'Hasil gabungan sudah dapat dilihat pegawai.'}[p.status]??'';
 const attr=(label,value,sub='')=>`<div class="period-attr"><span>${label}</span><b>${value}</b>${sub?`<p>${sub}</p>`:''}</div>`;
 const periodRows=pp.visible.map(x=>{const active=Number(x.id)===Number(p.id);return`<tr class="${active?'period-row-active':''}" ${active?'aria-current="true"':''}><td><b>${esc(x.name)}</b></td><td class="hide-mobile">${date(x.start_date)}</td><td class="hide-mobile">${date(x.end_date)}</td><td>${badge(x.status)}</td><td class="hide-medium">${x.published_at?date(String(x.published_at).slice(0,10)):'—'}</td><td style="text-align:right">${active?`<span class="badge pill-blue">${icon('check')}Terpilih</span>`:`<button class="btn btn-outline btn-sm" data-action="change-period" data-id="${x.id}">Pilih</button>`}</td></tr>`;}).join('');
 shell(`${pageHead('Periode & penilai',isSuper()?'Tetapkan periode, pasangan penilai, dan publikasi hasil.':`Pasangan penilai untuk ${esc(data.user.opd_name)}. Periode dikelola administrator kabupaten.`,isSuper()?`<button class="btn btn-primary" data-action="period-add">${icon('plus')}Periode baru</button>`:'','PENGELOLAAN')}<section class="card"><div class="section-heading"><div><h2>Daftar periode</h2><p>${data.periods.length} periode penilaian. Pilih periode untuk melihat rincian dan penugasannya di bawah.</p></div></div><div class="filterbar card-filters">${filterSelect('periods','year','Semua tahun',years.map(y=>[y,y]))}${filterSelect('periods','status','Semua status',['draft','open','closed','published'].map(s=>[s,statusLabels[s]]))}</div>${periodRows?`<div class="table-wrap"><table class="table"><thead><tr><th>Periode</th><th class="hide-mobile">Mulai</th><th class="hide-mobile">Selesai</th><th>Status</th><th class="hide-medium">Dipublikasikan</th><th style="text-align:right">Tindakan</th></tr></thead><tbody>${periodRows}</tbody></table></div>`:empty('Tidak ada periode yang cocok','Sesuaikan filter tahun atau status periode.')}${pageNav('periods',pp,'periode')}</section><section class="card card-pad" style="margin-top:22px"><div class="between"><div><div class="eyebrow">PERIODE TERPILIH</div><h2>${esc(p.name)} ${badge(p.status)}</h2><p class="small muted" style="margin-top:9px">${esc(statusHint)}</p></div>${periodButton()}</div><div class="period-attrs">${attr('Tanggal mulai',date(p.start_date))}${attr('Tanggal selesai',date(p.end_date))}${attr('Durasi',`${days} hari`)}${attr('Status',badge(p.status))}${attr('Dipublikasikan',esc(publishedAt))}${attr('Penugasan',`${a.length}`,`${sent} terkirim${a.length?` · ${Math.round(sent/a.length*100)}%`:''}`)}</div><div class="form-actions" style="margin-bottom:0"><span class="small muted">${p.status==='published'?'Periode ini telah selesai.':p.status==='draft'?'Lengkapi penilai, lalu buka periode.':p.status==='open'?'Tutup periode setelah pengisian selesai.':'Publikasikan agar hasil dapat dilihat pegawai.'}</span><div class="flexline">${p.status==='draft'?'<button class="btn btn-outline" data-action="assignment-add">'+icon('user-plus')+'Tambah penilai</button>':''}${isSuper()&&p.status==='closed'?'<button class="btn btn-outline" data-action="period-status" data-status="open">Buka kembali</button>':''}${isSuper()&&p.status!=='published'?`<button class="btn btn-primary" data-action="period-status" data-status="${({draft:'open',open:'closed',closed:'published'})[p.status]}">${icon(({draft:'play',open:'lock-keyhole',closed:'send'})[p.status])}${({draft:'Buka periode',open:'Tutup periode',closed:'Publikasikan hasil'})[p.status]}</button>`:''}</div></div></section><section class="card" style="margin-top:22px"><div class="section-heading"><div><h2>Distribusi penilai</h2><p>Penugasan pada ${esc(p.name)}. Peran menunjukkan hubungan penilai terhadap pegawai yang dinilai.</p></div></div><div class="filterbar card-filters">${searchBox('assignments','Cari pegawai dinilai atau penilai')}${opdSelect('periods-opd')}${filterSelect('assignments','role','Semua peran',Object.entries(roleLabels))}${filterSelect('assignments','status','Semua status',['pending','draft','submitted'].map(s=>[s,statusLabels[s]]))}</div>${ap.visible.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Pegawai dinilai</th>${isSuper()?'<th class="hide-mobile">OPD</th>':''}<th>Penilai</th><th>Peran penilai</th><th>Status</th>${p.status==='draft'?'<th></th>':''}</tr></thead><tbody>${ap.visible.map(x=>`<tr><td>${esc(x.subject_name)}</td>${isSuper()?`<td class="hide-mobile">${esc(x.opd_code)}</td>`:''}<td>${esc(x.rater_name)}</td><td><span class="badge pill-blue">${roleLabels[x.rater_role]}</span></td><td>${badge(x.status)}</td>${p.status==='draft'?`<td><button class="btn btn-ghost btn-sm" data-action="assignment-delete" data-id="${x.id}" aria-label="Hapus penugasan">${icon('trash-2')}</button></td>`:''}</tr>`).join('')}</tbody></table></div>`:a.length?empty('Tidak ada penugasan ditemukan','Sesuaikan kata pencarian atau filter penugasan.'):empty('Belum ada penilai','Tambahkan pasangan pegawai dan penilai sebelum membuka periode.')}${pageNav('assignments',ap,'penugasan')}</section>`,'Periode & penilai');
}
function opd(){if(!isSuper())return denied();const hit=matcher('opd'),rows=data.opds.filter(o=>pass('opd','active',Number(o.active)?'1':'0')&&hit(o.name,o.code)),p=paginate('opd',rows);
 shell(`${pageHead('OPD & pengaturan','Kelola perangkat daerah dan identitas kabupaten pada satu kerangka SIKAP 360.',`<button class="btn btn-primary" data-action="opd-add">${icon('plus')}Tambah OPD</button>`,'PENGELOLAAN')}<div class="dashboard-grid"><section class="card"><div class="section-heading"><div><h2>Organisasi Perangkat Daerah</h2><p>Setiap pegawai, struktur, dan penugasan berada di dalam satu OPD.</p></div></div><div class="filterbar card-filters">${searchBox('opd','Cari nama atau kode OPD')}${filterSelect('opd','active','Semua status',[['1','Aktif'],['0','Nonaktif']])}</div>${p.visible.length?`<div class="table-wrap"><table class="table"><thead><tr><th>OPD</th><th>Kode</th><th>Pegawai aktif</th><th>Status</th><th></th></tr></thead><tbody>${p.visible.map(o=>`<tr><td><b>${esc(o.name)}</b></td><td>${esc(o.code)}</td><td>${o.employee_count}</td><td><span class="badge ${Number(o.active)?'pill-green':'pill-gray'}">${Number(o.active)?'Aktif':'Nonaktif'}</span></td><td><button class="table-action" data-action="opd-edit" data-id="${o.id}">${icon('pencil')}Edit</button></td></tr>`).join('')}</tbody></table></div>`:data.opds.length?empty('Tidak ada OPD ditemukan','Sesuaikan kata pencarian atau filter status.'):empty('Belum ada OPD','Tambahkan OPD sebelum mendaftarkan pegawai.')}${pageNav('opd',p,'OPD',` · ${data.opds.reduce((s,o)=>s+Number(o.employee_count),0)} pegawai aktif`)}</section><aside class="dashboard-aside"><section class="card card-pad"><h2>Identitas kabupaten</h2><p class="small muted" style="margin:8px 0 18px">Nama tampil di halaman masuk, bilah samping, dan cetakan hasil.</p><form id="settings-form"><label class="field"><span>Nama kabupaten</span><input class="input" name="kabupaten_name" value="${esc(kabupaten())}" maxlength="120" required placeholder="Contoh: Hulu Sungai Selatan"></label><p class="small muted" style="margin:-6px 0 14px">Ditampilkan sebagai "Pemerintah Kabupaten ${esc(kabupaten())}".</p><button type="submit" class="btn btn-primary" style="width:100%">${icon('save')}Simpan pengaturan</button></form></section><section class="card card-pad"><h2>Peran akun</h2><div class="detail-lines" style="margin-top:14px"><div>Administrator kabupaten<b>Semua OPD, periode, pengaturan</b></div><div>Admin OPD<b>Pegawai & penilai OPD-nya</b></div><div>ASN<b>Menilai & melihat hasil</b></div></div><p class="small muted" style="line-height:1.8;margin-top:14px">Peran diatur pada formulir pegawai. Periode penilaian berlaku serentak untuk seluruh OPD.</p></section></aside></div>`,'OPD & pengaturan');
}
function opdModal(id){const o=data.opds.find(x=>Number(x.id)===Number(id))??{active:1};modal(`<h2 id="dialog-title">${id?'Edit':'Tambah'} OPD</h2><p>${id?'Perubahan nama berlaku untuk seluruh pegawai OPD ini.':'OPD baru langsung dapat dipilih pada formulir pegawai.'}</p><form id="opd-form"><input type="hidden" name="id" value="${o.id??''}"><label class="field"><span>Nama OPD</span><input class="input" name="name" value="${esc(o.name)}" maxlength="160" required placeholder="Contoh: Dinas Kesehatan"></label><div class="form-grid"><label class="field"><span>Kode singkat</span><input class="input" name="code" value="${esc(o.code)}" maxlength="20" required pattern="[A-Za-z0-9_\\-]{2,20}" placeholder="Contoh: DINKES" style="text-transform:uppercase"></label><label class="field"><span>Status</span><select class="select" name="active"><option value="1" ${Number(o.active)?'selected':''}>Aktif</option><option value="0" ${!Number(o.active)?'selected':''}>Nonaktif</option></select></label></div>${buttons('Simpan OPD')}</form>`);}
// Laman Metode: bobot komposisi periode terpilih, cara hitung, aturan komposisi, dan tujuh indikator. Administrator kabupaten menyunting bobot langsung pada kartu kondisi selama periode berstatus draf.
function method(){const p=data.period,w=p.weights,edit=isSuper()&&p.status==='draft',k1=w['atasan,bawahan,rekan'],sample={atasan:4.5,rekan:4,bawahan:4},sampleScore=Object.entries(k1).reduce((s,[r,v])=>s+sample[r]*v,0)/100*20;
 const swatch=r=>`<span class="flexline"><i class="swatch" style="--swatch:${roleColors[r]}"></i>${roleLabels[r]}</span>`;
 const line=(key,name,r,v)=>edit?`<label class="weight-field">${swatch(r)}<span class="weight-input"><input class="input" type="number" name="${key}|${r}" value="${v}" min="1" max="99" inputmode="numeric" required data-weight="${r}" aria-label="Bobot ${roleLabels[r].toLowerCase()}, ${name}">%</span></label>`:`<div>${swatch(r)}<b>${v}%</b></div>`;
 const lock=isSuper()&&!edit?`<div class="card card-pad weights-lock">${icon('lock')}<div><b>Bobot ${esc(p.name)} terkunci</b><p class="small muted">Periode berstatus ${esc(statusLabels[p.status].toLowerCase())}. Bobot terkunci sejak periode dibuka agar aturan penilaian tidak berubah selama penilaian berjalan maupun setelah nilai terlihat. Untuk mengubah bobot, pilih periode berstatus draf; periode baru menyalin bobot periode terbaru.</p></div></div>`:'';
 const cards=`<div class="method-grid">${conditions.map(([key,name,desc])=>`<section class="card method-card" data-condition="${key}"><span class="badge pill-blue">${name}</span><h2>${desc}</h2>${weightBar(w[key])}<div class="detail-lines">${Object.entries(w[key]).map(([r,v])=>line(key,name,r,v)).join('')}${edit?'<div class="weight-total" data-weight-total>Jumlah<b>100%</b></div>':''}</div></section>`).join('')}</div>`;
 shell(`${pageHead('Metode penilaian',`Komposisi bobot ${esc(p.name)}, indikator, dan cara nilai perilaku ASN dihitung.`,periodButton(),'PUSAT INFORMASI')}${edit?`<form id="weights-form">${cards}<div class="card card-pad weights-actions"><div><b>Ubah bobot ${esc(p.name)}</b><p class="small muted">Isi bilangan bulat 1–99; jumlah tiap kondisi harus 100%. Bobot ini hanya berlaku untuk ${esc(p.name)} dan terkunci saat periode dibuka.</p></div><div class="flexline"><button type="button" class="btn btn-outline" data-action="weights-default">${icon('rotate-ccw')}Bobot bawaan</button><button type="submit" class="btn btn-primary" id="weights-save">${icon('save')}Simpan bobot</button></div></div></form>`:cards+lock}<div class="bottom-grid"><section class="card guide-section"><h2>Cara nilai dihitung</h2><p>Rata-rata jawaban dihitung untuk setiap kelompok penilai. Rata-rata kelompok dikalikan bobot, kemudian dijumlahkan. Rata-rata tujuh indikator dikalikan 20 menjadi skala 20–100.</p><p style="margin-top:13px">Contoh Kondisi 1: atasan 4,5, rekan 4,0, bawahan 4,0 menghasilkan (4,5 × ${k1.atasan}% + 4 × ${k1.rekan}% + 4 × ${k1.bawahan}%) × 20 = ${fmt(sampleScore)}.</p></section><section class="card guide-section"><h2>Aturan komposisi</h2><ul><li>Setiap pegawai dinilai tepat satu atasan langsung.</li><li>Kelompok rekan sejawat dan bawahan yang digunakan masing-masing minimal satu penilai.</li><li>Kondisi mengikuti kelompok penilai yang dimiliki pegawai; komposisi lain tidak dapat dibuka.</li><li>Jumlah orang dalam kelompok tidak mengubah bobot kelompok, dan penilaian yang belum masuk tidak dihitung nol.</li><li>Bobot ditetapkan administrator kabupaten untuk tiap periode selama periode berstatus draf dan terkunci sejak periode dibuka. Hasil setiap periode dihitung dengan bobot periode itu sendiri.</li></ul></section></div><section class="card guide-section" style="margin-top:22px"><h2>Tujuh indikator BerAKHLAK</h2><p>Setiap indikator dinilai dengan bilangan bulat 1 (sangat kurang) sampai 5 (sangat baik).</p><ol class="indicator-list">${data.indicators.map(i=>`<li><b>${esc(i.name)}</b><span>${esc(i.description)}</span></li>`).join('')}</ol><p class="small" style="margin-top:18px">Bobot bawaan 60/25/15, 75/25, dan 85/15 mengikuti gambar referensi. Rubrik ini merupakan rancangan aplikasi dan perlu ditetapkan instansi sebelum digunakan secara resmi.</p></section>`,'Metode');
 if(edit)weightTotals();
}
// Jumlah dan bilah bobot tiap kartu kondisi mengikuti isian; tombol simpan aktif hanya bila setiap kondisi berjumlah 100%.
function weightTotals(){const form=document.getElementById('weights-form');if(!form)return;let ok=true;
 form.querySelectorAll('[data-condition]').forEach(card=>{const inputs=[...card.querySelectorAll('[data-weight]')],sum=inputs.reduce((s,i)=>s+(Number(i.value)||0),0),total=card.querySelector('[data-weight-total]');
  inputs.forEach(i=>{card.querySelector(`[data-bar="${i.dataset.weight}"]`).style.width=`${Math.max(0,Math.min(100,Number(i.value)||0))}%`;});
  total.classList.toggle('bad',sum!==100);total.querySelector('b').textContent=sum===100?'100%':`${fmt(sum)}% · harus 100%`;if(sum!==100)ok=false;});
 document.getElementById('weights-save').disabled=!ok;}
// Laman Panduan: langkah menilai, membaca hasil, alur pengelolaan (khusus administrator), serta objektivitas dan kerahasiaan.
function guide(){const flow=isSuper()?['Periksa OPD & pengaturan, lengkapi Data pegawai, dan tetapkan peran Admin OPD bagi pengelola tiap OPD.','Tetapkan atasan langsung pada Struktur organisasi. Rekan sejawat dan bawahan diturunkan otomatis.','Buat periode triwulan berstatus draf pada Periode & penilai. Periode baru menyalin bobot periode terbaru; ubah bila perlu pada laman Metode selama periode masih draf.','Tekan Buat penugasan pada Struktur organisasi, atau tambahkan penilai satu per satu.','Buka periode setelah komposisi setiap pegawai sah. Distribusi penilai dan bobot terkunci sejak periode dibuka.','Tutup periode setelah pengisian selesai, lalu publikasikan hasil.']:['Lengkapi Data pegawai OPD Anda.','Tetapkan atasan langsung pada Struktur organisasi. Rekan sejawat dan bawahan diturunkan otomatis.','Saat periode berstatus draf, tekan Buat penugasan pada Struktur organisasi atau tambahkan penilai pada Periode & penilai.','Pantau status pengiriman pada Distribusi penilai. Administrator kabupaten membuka, menutup, dan mempublikasikan periode.'];
 shell(`${pageHead('Panduan','Langkah memberikan penilaian, membaca hasil, dan menjaga objektivitas.','','PUSAT INFORMASI')}<div class="bottom-grid" style="margin-top:0"><section class="card guide-section"><h2>Cara memberikan penilaian</h2><ol><li>Buka Penilaian saya dan pilih pegawai.</li><li>Isi tujuh indikator BerAKHLAK pada skala 1 sampai 5.</li><li>Simpan draf untuk melanjutkan nanti.</li><li>Periksa jawaban, kemudian kirim penilaian.</li><li>Lihat hasil pribadi setelah periode dipublikasikan.</li></ol></section><section class="card guide-section"><h2>Membaca hasil penilaian</h2><p>Hasil pribadi tampil setelah seluruh penilai mengirim dan administrator mempublikasikan periode. Nilai gabungan memakai skala 20–100, disertai profil tiap indikator dan komposisi kelompok penilai.</p><p style="margin-top:13px">Bobot tiap kelompok penilai dan cara hitungnya dijelaskan pada laman Metode.</p><a href="#method" class="text-link" style="margin-top:13px">Buka laman Metode ${icon('arrow-right')}</a></section></div>${isAdmin()?`<section class="card guide-section" style="margin-top:22px"><h2>Alur pengelolaan periode</h2><ol>${flow.map(x=>`<li>${x}</li>`).join('')}</ol></section>`:''}<section class="card guide-section" style="margin-top:22px"><h2>Objektivitas dan kerahasiaan</h2><p>Berikan penilaian berdasarkan perilaku yang diamati selama periode. Akun pegawai hanya melihat hasil gabungan, tanpa identitas penilai. Administrator mengelola penugasan dan status pengiriman. Database tetap menyimpan hubungan penilai untuk audit dan memerlukan pembatasan akses server.</p><p style="margin-top:12px">Integrasi SIMPEG dan manajemen talenta belum dihubungkan.</p></section>`,'Panduan');}
function denied(){shell(empty('Akses dibatasi','Halaman ini hanya tersedia untuk administrator.'),'Akses dibatasi');}
function login(){data=null;app.innerHTML=`<div class="login-page"><section class="login-brand"><div>${brand()}</div><div><div class="eyebrow" style="color:#a9c0ea" id="login-region">PEMERINTAH KABUPATEN</div><h1>Sudut pandang utuh.<br><span>Perilaku yang terus tumbuh.</span></h1><p>Ruang penilaian perilaku ASN dari atasan, rekan sejawat, dan bawahan.</p><ul class="check-list"><li>${icon('users')}Penilaian dari berbagai peran</li><li>${icon('chart-no-axes-combined')}Tujuh indikator BerAKHLAK</li><li>${icon('shield-check')}Akses hasil sesuai kewenangan</li></ul></div><small style="color:#a9bfe6">© 2026 SIKAP 360</small></section><section class="login-main">${themeToggle('login-theme')}<form class="login-form" id="login-form"><span class="badge pill-blue">PORTAL ASN</span><h1 style="margin-top:20px">Selamat datang kembali</h1><p>Masuk menggunakan akun SIKAP yang diberikan oleh administrator instansi.</p><div id="login-error" hidden class="login-error"></div><label class="field"><span>Email / NIP</span><input name="username" class="input" type="text" autocomplete="username" autocapitalize="none" spellcheck="false" placeholder="NIP 18 digit" required></label><label class="field"><span>Kata sandi</span><input name="password" class="input" type="password" autocomplete="current-password" required placeholder="Kata sandi"></label><button class="btn btn-primary" type="submit" data-busy="Memeriksa akun…">Masuk ke SIKAP ${icon('arrow-right')}</button>${DEMO?'<button type="button" class="btn btn-outline" style="width:100%;margin-top:12px" data-action="enter-demo">Masuk ruang demo</button>':''}<p class="login-footer">Lupa kata sandi? Hubungi administrator instansi.</p></form></section></div>`;icons();
 request('info').then(i=>{const el=document.getElementById('login-region');if(el)el.textContent=`PEMERINTAH KABUPATEN ${String(i.kabupaten_name??'').toUpperCase()}`;}).catch(()=>{});}
function modal(html){document.getElementById('dialog-content').innerHTML=html;document.getElementById('dialog').showModal();icons();}
function closeModal(){document.getElementById('dialog').close();}
function buttons(label){return`<div class="modal-action"><button type="button" class="btn btn-outline" data-action="close-modal">Batal</button><button type="submit" class="btn btn-primary">${label}</button></div>`;}
function confirmModal(title,text,action,extra=''){modal(`<h2 id="dialog-title">${title}</h2><p>${text}</p><div class="modal-action"><button class="btn btn-outline" data-action="close-modal">Kembali</button><button class="btn btn-primary" data-action="${action}" data-busy="${action==='confirm-submit'?'Mengirim…':'Memproses…'}" ${extra}>Konfirmasi</button></div>`);}
function employeeModal(id){const e=data.employees.find(x=>Number(x.id)===Number(id))??{},leaders=crossLeaders();modal(`<h2 id="dialog-title">${id?'Edit':'Tambah'} pegawai</h2><p>${id?'Perbarui identitas pegawai. Kata sandi kosong berarti tidak diganti.':'Akun ASN dibuat bersama data pegawai. Kata sandi awal kosong berarti memakai NIP.'}</p><form id="employee-form"><input type="hidden" name="id" value="${e.id??''}"><div class="form-grid">${[['name','Nama lengkap','text'],['nip','NIP (18 digit)','text'],['email','Email akun','email'],['position','Jabatan','text'],['unit','Unit kerja','text'],['grade','Pangkat / golongan','text']].map(([name,label,type])=>`<label class="field"><span>${label}</span><input name="${name}" class="input" type="${type}" value="${esc(e[name])}" maxlength="${name==='nip'?18:160}" required></label>`).join('')}${isSuper()?`<label class="field"><span>OPD</span><select class="select" name="opd_id" required>${data.opds.filter(o=>Number(o.active)||Number(o.id)===Number(e.opd_id)).map(o=>`<option value="${o.id}" ${Number(e.opd_id??(opdFilter!=='all'?opdFilter:data.opds[0]?.id))===Number(o.id)?'selected':''}>${esc(o.name)}</option>`).join('')}</select></label><label class="field"><span>Peran akun</span><select class="select" name="role" ${Number(id)===Number(data.user.id)?'disabled':''}>${[['asn','ASN'],['admin_opd','Admin OPD'],['admin','Administrator kabupaten']].map(([v,l])=>`<option value="${v}" ${(e.role??'asn')===v?'selected':''}>${l}</option>`).join('')}</select></label>`:`<label class="field full"><span>OPD</span><input class="input" value="${esc(data.user.opd_name)}" disabled></label>`}<label class="field full"><span>Atasan langsung</span><select class="select" name="supervisor_id"><option value="">Tanpa atasan (puncak struktur)</option>${e.supervisor_id&&!data.employees.some(x=>Number(x.id)===Number(e.supervisor_id))?`<option value="${e.supervisor_id}" data-any="1" selected>${esc(e.supervisor_name)} · ${esc(e.supervisor_position)}</option>`:''}${data.employees.filter(x=>Number(x.active)&&Number(x.id)!==Number(id)).map(x=>`<option value="${x.id}" data-opd="${x.opd_id}"${leaders.has(Number(x.id))?' data-any="1"':''} ${Number(e.supervisor_id)===Number(x.id)?'selected':''}>${esc(x.name)} · ${esc(x.position)}</option>`).join('')}</select></label><label class="field full"><span>${id?'Kata sandi baru (opsional)':'Kata sandi awal'}</span><input name="password" class="input" type="password" minlength="12" autocomplete="new-password" placeholder="${id?'Minimal 12 karakter':'Kosongkan untuk memakai NIP'}"></label></div>${buttons('Simpan pegawai')}</form>`);sameOpdOptions('employee-form','opd_id','supervisor_id',isSuper()?null:data.user.opd_id);}
// Batasi pilihan atasan/penilai ke OPD yang sama; dipanggil ulang saat OPD atau pegawai berubah.
// Pegawai yang sudah membawahi pegawai OPD lain (mis. Bupati bagi kepala OPD): pimpinan lintas OPD yang boleh dipilih sebagai atasan dari OPD mana pun.
function crossLeaders(){const byId=Object.fromEntries(data.employees.map(e=>[Number(e.id),e]));return new Set(data.employees.filter(e=>Number(e.active)&&byId[Number(e.supervisor_id)]&&Number(byId[Number(e.supervisor_id)].opd_id)!==Number(e.opd_id)).map(e=>Number(e.supervisor_id)));}
// Opsi bertanda data-any (pimpinan lintas OPD, mis. Bupati) tidak pernah disembunyikan.
function sameOpdOptions(formId,sourceName,targetName,fixedOpd=null){const f=document.getElementById(formId);const apply=()=>{const src=f.elements[sourceName];const opd=fixedOpd??(src?.selectedOptions?.[0]?.dataset.opd??src?.value);const t=f.elements[targetName];let keep=false;[...t.options].forEach(o=>{if(!o.value)return;o.hidden=opd!=null&&!o.dataset.any&&String(o.dataset.opd)!==String(opd);if(o.selected&&!o.hidden)keep=true;});if(!keep)t.value='';};apply();f.addEventListener('change',e=>{if(e.target.name===sourceName)apply();});}
const quarterRoman=['I','II','III','IV'],quarterMonths=['Januari – Maret','April – Juni','Juli – September','Oktober – Desember'];
function quarterRange(year,quarter){const m=(quarter-1)*3;return{name:`Triwulan ${quarterRoman[quarter-1]} ${year}`,start:`${year}-${String(m+1).padStart(2,'0')}-01`,end:`${year}-${String(m+3).padStart(2,'0')}-${new Date(year,m+3,0).getDate()}`};}
function periodModal(){const today=new Date(),next=Math.floor(today.getMonth()/3)+2,year=next>4?today.getFullYear()+1:today.getFullYear(),quarter=next>4?1:next,taken=new Set(data.periods.map(p=>p.start_date));
 modal(`<h2 id="dialog-title">Buat periode penilaian</h2><p>Periode penilaian berjalan per triwulan kalender. Periode baru berstatus draf sampai penilai ditetapkan.</p><form id="period-form"><div class="form-grid"><label class="field"><span>Tahun</span><select class="select" name="year">${Array.from({length:4},(_,i)=>today.getFullYear()-1+i).map(y=>`<option value="${y}" ${y===year?'selected':''}>${y}</option>`).join('')}</select></label><label class="field"><span>Triwulan</span><select class="select" name="quarter">${quarterRoman.map((r,i)=>`<option value="${i+1}" ${i+1===quarter?'selected':''}>Triwulan ${r} · ${quarterMonths[i]}</option>`).join('')}</select></label></div><div class="period-preview" id="period-preview"></div>${buttons('Buat periode')}</form>`);
 const preview=()=>{const f=document.getElementById('period-form'),r=quarterRange(Number(f.year.value),Number(f.quarter.value)),exists=taken.has(r.start);document.getElementById('period-preview').innerHTML=`${icon('calendar-range')}<div><b>${esc(r.name)}</b><p>${date(r.start)} sampai ${date(r.end)}</p>${exists?'<p class="warn-text">Periode ini sudah ada.</p>':''}</div>`;f.querySelector('button[type=submit]').disabled=exists;icons();};
 preview();document.getElementById('period-form').addEventListener('change',preview);}
function assignmentModal(){const pool=data.employees.filter(e=>Number(e.active)&&inOpd(e)),options=data.opds.filter(o=>pool.some(e=>Number(e.opd_id)===Number(o.id))).map(o=>`<optgroup label="${esc(o.name)}">${pool.filter(e=>Number(e.opd_id)===Number(o.id)).map(e=>`<option value="${e.id}" data-opd="${e.opd_id}">${esc(e.name)}</option>`).join('')}</optgroup>`).join('');modal(`<h2 id="dialog-title">Tetapkan penilai</h2><p>Peran dipilih berdasarkan hubungan penilai terhadap pegawai yang dinilai.</p><form id="assignment-form"><label class="field"><span>Pegawai yang dinilai</span><select class="select" name="subject_id" required><option value="">Pilih pegawai</option>${options}</select></label><label class="field"><span>Pegawai penilai</span><select class="select" name="rater_id" required><option value="">Pilih penilai</option>${options}</select></label><label class="field"><span>Peran penilai terhadap pegawai</span><select class="select" name="rater_role"><option value="atasan">Atasan</option><option value="rekan">Rekan sejawat</option><option value="bawahan">Bawahan</option></select></label>${buttons('Tetapkan penilai')}</form>`);sameOpdOptions('assignment-form','subject_id','rater_id');}
async function saveDraft(){if(!editing)return;const answer=await request('save_draft',{id:editing.id,version:editing.version,answers:editing.answers,feedback:document.getElementById('feedback').value});editing.version=answer.version;dirty=false;await refresh();return answer;}
// Keluar selalu berakhir di halaman masuk. 401 berarti sesi server sudah berakhir; 403 berarti token CSRF tab ini usang (sesi diganti tab lain), maka ambil token baru lalu coba sekali lagi.
async function logout(){
 try{await request('logout');}
 catch(e){
  if(e.status===403){try{await refresh();await request('logout');}catch(e2){if(e2.status!==401)notify(e2.message,true);}}
  else if(e.status!==401)notify(e.message,true);
 }
 data=null;editing=null;submitIds=[];dirty=false;periodId=0;opdFilter='all';resetTables();
 sessionStorage.removeItem('sikap_period');sessionStorage.removeItem('sikap_opd');
 location.hash='login';login();
}
// Selama permintaan berjalan, tombol pemicu menampilkan spinner dan label proses: data-busy, atau "Menyimpan…" untuk tombol submit formulir. Bila server belum menjawab setelah 10 detik, pengguna diberi tahu bahwa server lambat agar tidak mengira tombol macet.
async function perform(fn,trigger=null){if(busy)return;busy=true;const busyLabel=trigger?.dataset.busy??(trigger?.form&&trigger.type==='submit'?'Menyimpan…':null),label=trigger?.innerHTML,slow=setTimeout(()=>notify('Server lambat merespons. Mohon tunggu dan jangan tutup halaman ini.'),10000);if(busyLabel){trigger.setAttribute('aria-busy','true');trigger.innerHTML=`<span class="loading loading-spinner loading-xs" aria-hidden="true"></span>${esc(busyLabel)}`;}const formControls=[...document.querySelectorAll('#evaluation-form input,#evaluation-form textarea')].map(node=>({node,disabled:node.disabled}));formControls.forEach(({node})=>node.disabled=true);document.querySelectorAll('button[data-action="confirm-submit"],button[data-action="confirm-period-status"],button[data-action="save-draft"],.modal-box button[type="submit"]').forEach(b=>b.disabled=true);try{await fn();}catch(e){notify(e.message,true);}finally{clearTimeout(slow);busy=false;if(busyLabel){trigger.removeAttribute('aria-busy');trigger.innerHTML=label;}formControls.forEach(({node,disabled})=>node.disabled=disabled);document.querySelectorAll('button[data-action="confirm-submit"],button[data-action="confirm-period-status"],button[data-action="save-draft"],.modal-box button[type="submit"]').forEach(b=>b.disabled=false);}}
function csv(filename,headers,rows){const safe=v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return'"'+s.replaceAll('"','""')+'"';};const blob=new Blob(['\ufeff'+[headers,...rows].map(row=>row.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
let submitIds=[];
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(el.disabled||busy){e.preventDefault();return;}
 if(action==='menu'){document.querySelector('.sidebar')?.classList.toggle('open');document.querySelector('.nav-backdrop')?.classList.toggle('open');return;}
 if(action==='close-modal'){closeModal();return;}
 if(action==='theme'){setTheme(isDark()?'light':'dark',true);el.closest('details')?.removeAttribute('open');return;}
 if(action==='filter'){const t=tbl(el.dataset.table);t.f[el.dataset.filter]=el.dataset.value;t.page=1;rerender();return;}
 if(action==='page'){tbl(el.dataset.table).page=Number(el.dataset.value);rerender();return;}
 if(action==='select-period'){modal(`<h2 id="dialog-title">Pilih periode</h2><p>Data penilaian mengikuti periode yang Anda pilih.</p><div class="period-list">${data.periods.map(p=>{const cur=Number(p.id)===Number(data.period.id);return`<button type="button" class="period-option${cur?' active':''}" data-action="change-period" data-id="${p.id}" ${cur?'aria-current="true"':''}><span><b>${esc(p.name)}</b><small>${date(p.start_date)} – ${date(p.end_date)}</small></span>${badge(p.status)}</button>`;}).join('')}</div>`);return;}
 if(action==='profile'){modal(`<h2 id="dialog-title">Profil saya</h2><p>${esc(data.user.name)}</p><div class="detail-lines">${[['NIP',data.user.nip],['Jabatan',data.user.position],['OPD',data.user.opd_name],['Unit kerja',data.user.unit],['Email',data.user.email]].map(([k,v])=>`<div><span>${k}</span><b>${esc(v)}</b></div>`).join('')}</div>${!DEMO?'<form id="password-form" style="margin-top:24px"><label class="field"><span>Kata sandi saat ini</span><input class="input" name="current_password" type="password" autocomplete="current-password" required></label><label class="field"><span>Kata sandi baru (minimal 12 karakter)</span><input class="input" name="password" type="password" autocomplete="new-password" minlength="12" required></label>'+buttons('Ganti kata sandi')+'</form>':'<div class="modal-action"><button class="btn btn-outline" data-action="demo-reset">Reset data demo</button><button class="btn btn-primary" data-action="close-modal">Tutup</button></div>'}`);return;}
 if(action==='notices'){const c=counts();notify(`${c.total-c.done} tugas belum terkirim. ${c.draft} draf tersimpan.`);return;}
 if(action==='employee-add'||action==='employee-edit'){employeeModal(el.dataset.id);return;}
 if(action==='period-add'){periodModal();return;}
 if(action==='weights-default'){const f=document.getElementById('weights-form');for(const [key,roles] of Object.entries(defaultWeights))for(const [r,v] of Object.entries(roles))f.elements[`${key}|${r}`].value=v;dirty=true;weightTotals();return;}
 if(action==='opd-add'||action==='opd-edit'){opdModal(el.dataset.id);return;}
 if(action==='assignment-add'){assignmentModal();return;}
 if(action==='assignment-delete'){confirmModal('Hapus penugasan?','Pasangan penilai ini akan dihapus dari periode draf.','confirm-assignment-delete',`data-id="${el.dataset.id}"`);return;}
 if(action==='period-status'){const status=el.dataset.status;confirmModal(({open:'Buka periode?',closed:'Tutup periode?',published:'Publikasikan hasil?'})[status],({open:'Komposisi penilai akan divalidasi dan dikunci. Pegawai dapat mengisi penilaian sampai periode ditutup.',closed:'Pengisian akan dikunci. Pastikan penugasan telah selesai sebelum melanjutkan.',published:'Hasil gabungan akan tersedia untuk pegawai. Seluruh penugasan harus sudah terkirim.'})[status],'confirm-period-status',`data-status="${status}"`);return;}
 if(action==='submit-one'){
  if(data.indicators.some(i=>!editing.answers[i.id])){notify('Lengkapi ketujuh indikator sebelum mengirim.',true);return;}
  submitIds=[Number(editing.id)];confirmModal('Kirim penilaian ini?','Jawaban akan disimpan dan dikunci setelah dikirim. Periksa seluruh nilai sebelum melanjutkan.','confirm-submit','data-single="yes"');return;
 }
 if(action==='submit-ready'){submitIds=data.tasks.filter(t=>t.status==='draft'&&data.indicators.every(i=>t.answers[i.id])).map(t=>Number(t.id));confirmModal(`Kirim ${submitIds.length} penilaian?`,'Seluruh draf lengkap akan dikunci setelah dikirim. Draf yang belum lengkap tetap tersimpan.','confirm-submit');return;}
 if(action==='logout'&&dirty&&!confirm('Ada perubahan yang belum disimpan. Keluar tanpa menyimpan?'))return;
 if(action==='print'){window.print();return;}
 if(action==='tree-toggle'){const li=el.closest('.tree-node');li.classList.toggle('collapsed');el.setAttribute('aria-expanded',String(!li.classList.contains('collapsed')));return;}
 if(action==='assignment-generate'){confirmModal('Buat penugasan dari struktur?',`Untuk periode <b>${esc(data.period.name)}</b>${isSuper()?(opdFilter==='all'?' pada <b>seluruh OPD</b>':` pada <b>${esc(opdName(opdFilter))}</b>`):''}: atasan langsung menjadi penilai atasan, sesama pejabat seatasan atau staf satu unit (UNOR) menjadi rekan sejawat, dan bawahan langsung menjadi penilai bawahan. Kelompok rekan/bawahan berjumlah kurang dari 3 dilewati. Pasangan yang sudah ada tidak diduplikasi.`,'confirm-assignment-generate');return;}
 if(action==='export-structure'){const name=id=>data.employees.find(x=>Number(x.id)===Number(id))?.name??'';csv('SIKAP-Struktur-Organisasi.csv',['Nama','NIP','Jabatan','OPD','Unit','Atasan langsung'],data.employees.filter(inOpd).map(e=>[e.name,e.nip,e.position,e.opd_name,e.unit,name(e.supervisor_id)||e.supervisor_name||'']));return;}
 if(action==='export-employees'){csv('SIKAP-Data-Pegawai.csv',['Nama','NIP','Jabatan','OPD','Unit','Email','Akun'],data.employees.filter(inOpd).map(e=>[e.name,e.nip,e.position,e.opd_name,e.unit,e.email,e.role]));return;}
 perform(async()=>{
  if(action==='change-period'){if(dirty&&!confirm('Ada perubahan yang belum disimpan. Tinggalkan formulir?'))return;dirty=false;periodId=Number(el.dataset.id);resetTables(true);closeModal();await refresh();render();}
  if(action==='switch-role'){await request('demo_role');await refresh();render();}
  if(action==='demo-reset'){await request('demo_reset');periodId=1;closeModal();await refresh();location.hash='dashboard';render();notify('Data demo telah direset.');}
  if(action==='enter-demo'){await refresh();location.hash='dashboard';render();}
  if(action==='logout')await logout();
  if(action==='save-draft'){await saveDraft();notify('Draf penilaian tersimpan.');}
  if(action==='confirm-submit'){
   if(el.dataset.single==='yes')await saveDraft();
   const response=await request('submit',{ids:submitIds});dirty=false;closeModal();await refresh();location.hash='assessments';render();notify(`${response.count} penilaian berhasil dikirim.`);
  }
  if(action==='confirm-period-status'){await request('period_status',{status:el.dataset.status});closeModal();await refresh();periods();notify('Status periode diperbarui.');}
  if(action==='confirm-assignment-generate'){const r=await request('assignment_generate',isSuper()&&opdFilter!=='all'?{opd_id:Number(opdFilter)}:{});closeModal();await refresh();render();if(r.warnings.length)modal(`<h2 id="dialog-title">${r.created} penugasan dibuat</h2><p>${r.skipped} pasangan sudah ada dan dilewati. Perhatikan catatan berikut:</p><ul class="small muted" style="line-height:1.8;padding-left:18px;max-height:40vh;overflow:auto">${r.warnings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="modal-action"><a href="#periods" class="btn btn-outline" data-action="close-modal">Lihat distribusi</a><button class="btn btn-primary" data-action="close-modal">Tutup</button></div>`);else notify(`${r.created} penugasan dibuat, ${r.skipped} dilewati.`);}
  if(action==='confirm-assignment-delete'){await request('assignment_delete',{id:Number(el.dataset.id)});closeModal();await refresh();periods();notify('Penugasan dihapus.');}
 },el);
});
document.addEventListener('input',async e=>{
 if(e.target.matches('[data-indicator]')){editing.answers[e.target.dataset.indicator]=Number(e.target.value);dirty=true;const n=Object.keys(editing.answers).length;document.getElementById('answer-count').textContent=`${n} / 7 terjawab`;document.getElementById('answer-progress').value=n;const i=data.indicators.find(i=>Number(i.id)===Number(e.target.dataset.indicator));document.getElementById(`check-${i.id}`).innerHTML=icon('circle-check')+esc(i.name);document.getElementById(`check-${i.id}`).classList.add('answered');icons();}
 if(e.target.id==='feedback')dirty=true;
 if(e.target.matches('[data-weight]')){dirty=true;weightTotals();}
 if(e.target.dataset.search){const id=e.target.id,pos=e.target.selectionStart,t=tbl(e.target.dataset.search);t.q=e.target.value;t.page=1;await rerender();const input=document.getElementById(id);if(input){input.focus();input.setSelectionRange(pos,pos);}}
});
document.addEventListener('change',e=>{if(e.target.dataset.filter){const t=tbl(e.target.dataset.table);t.f[e.target.dataset.filter]=e.target.value;t.page=1;rerender();}if(['employee-opd','structure-opd','periods-opd'].includes(e.target.id)){opdFilter=e.target.value;tbl('assignments').page=1;sessionStorage.setItem('sikap_opd',opdFilter);({'employee-opd':employees,'structure-opd':structure,'periods-opd':periods})[e.target.id]();}});
opdFilter=sessionStorage.getItem('sikap_opd')||'all';
// Id formulir dibaca lewat getAttribute: pada formulir yang memuat <input name="id"> (pegawai, OPD), form.id menunjuk elemen input itu (DOM clobbering). Semua formulir kecuali method="dialog" (latar modal) dicegah terkirim biasa, agar isian, termasuk kata sandi, tidak pernah berpindah ke URL.
document.addEventListener('submit',e=>{
 const form=e.target,id=form.getAttribute('id');if(form.getAttribute('method')==='dialog')return;e.preventDefault();if(!['login-form','employee-form','period-form','assignment-form','password-form','supervisor-form','opd-form','settings-form','weights-form'].includes(id))return;const fields=Object.fromEntries(new FormData(form));
 perform(async()=>{
  if(id==='login-form'){
   try{await request('login',fields);await refresh();location.hash='dashboard';render();}catch(err){const box=document.getElementById('login-error');box.hidden=false;box.textContent=err.message;}return;
  }
  // Isian bobot bernama "kunci|peran" disusun menjadi tabel bertingkat seperti di server.
  if(id==='weights-form'){const weights={};for(const [name,value] of Object.entries(fields)){const [key,role]=name.split('|');(weights[key]??={})[role]=Number(value);}await request('weights_save',{weights});dirty=false;await refresh();render();notify(`Bobot ${data.period.name} disimpan.`);return;}
  const action=({'employee-form':'employee_save','period-form':'period_create','assignment-form':'assignment_create','password-form':'password_change','supervisor-form':'supervisor_set','opd-form':'opd_save','settings-form':'settings_save'})[id];await request(action,fields);closeModal();await refresh();render();notify('Perubahan berhasil disimpan.');
 },e.submitter??form.querySelector('[type=submit]'));
});
const views={dashboard,assessments,results,employees,structure,periods,opd,method,guide};
// Gambar ulang rute aktif tanpa menyentuh status tabel (dipakai pencarian, filter, dan pagination).
function rerender(){if(route==='evaluate'||route==='login')return render();return(views[route]??dashboard)();}
function render(){if(!data){login();return;}const hash=location.hash.slice(1)||'dashboard';route=hash.split('/')[0];document.title=`SIKAP 360 | ${{dashboard:'Dashboard',assessments:'Penilaian saya',results:'Hasil penilaian',employees:'Data pegawai',structure:'Struktur organisasi',periods:'Periode & penilai',opd:'OPD & pengaturan',method:'Metode',guide:'Panduan',evaluate:'Formulir penilaian',login:'Masuk'}[route]??'Dashboard'}`;editing=null;if(route==='evaluate')evaluate(hash.split('/')[1]);else if(route==='login')login();else(views[route]??dashboard)();}
window.addEventListener('hashchange',()=>{dirty=false;resetTables();render();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(a&&busy){e.preventDefault();return;}if(a&&dirty){if(!confirm('Ada perubahan yang belum disimpan. Tinggalkan formulir?'))e.preventDefault();else dirty=false;}});
try{await refresh();render();}catch(e){if(e.status===401){login();}else{app.innerHTML=`<div class="card empty" style="max-width:650px;margin:80px auto"><h1>SIKAP belum terhubung</h1><p style="margin:20px auto">${esc(e.message)}</p><button class="btn btn-primary" id="retry-load">Coba lagi</button></div>`;document.getElementById('retry-load').onclick=()=>location.reload();}}
